import fs from 'node:fs';
import {createHash} from 'node:crypto';
import {PythonSession} from './packages/safe-python/src/index.ts';
import {codecTypeMutationAuditCases,codecTypeMutationCancellationCases} from './packages/safe-python/src/codec-type-mutation-audit-cases.ts';
const reference=JSON.parse(fs.readFileSync('packages/safe-python/src/runtime/__snapshots__/codec-type-mutation-audit-3.14.7.json','utf8'));
const outputFd=fs.openSync('/tmp/safe-python-type-mutation-service-output','w+'),inputFd=fs.openSync('/tmp/safe-python-type-mutation-service-input','w+');
fs.writeSync(inputFd,Buffer.from('ready\n'),0,6,0);
let writes=0,reads=0,flushes=0,bytes=0;const results=[];
const hash=text=>createHash('sha256').update(text).digest('hex');
try {
  for(const row of [...codecTypeMutationAuditCases,...codecTypeMutationCancellationCases]){
    let offset=0;fs.ftruncateSync(outputFd,0);const controller=new AbortController(),cancel='throws' in row;
    const output={write(text){const data=Buffer.from(text);offset+=fs.writeSync(outputFd,data,0,data.length,offset);writes++;bytes+=data.length;},flush(){flushes++;fs.fsyncSync(outputFd);}};
    const input={readLine(){const data=Buffer.alloc(16);const length=fs.readSync(inputFd,data,0,data.length,0);reads++;if(cancel){controller.abort();if(row.throws)throw Error('service failed after cancellation');}return data.subarray(0,length).toString('utf8');}};
    const session=new PythonSession({limits:{maxSteps:1000000,maxAllocatedBytes:16000000,maxDepth:100},hashSeed:[1n,2n],signal:controller.signal,output,input});
    const result=session.exec(row.source),data=Buffer.alloc(offset);fs.readSync(outputFd,data,0,offset,0);const stdout=data.toString('utf8');
    const expected=cancel?undefined:reference.cases.find(test=>test.name===row.name).stdout;
    const next=cancel?session.eval('1'):undefined;
    const matches=cancel?result.status==='terminated'&&result.reason==='cancelled'&&next.status==='terminated'&&next.reason==='cancelled':result.status==='ok'&&stdout===expected;
    results.push({name:cancel?`${row.operation}/${row.stage}/${row.throws}`:row.name,sourceSha256:hash(row.source),status:result.status,reason:result.reason,next:next?.status,stdoutSha256:hash(stdout),expectedSha256:expected===undefined?undefined:hash(expected),matches});
  }
} finally{fs.closeSync(inputFd);fs.closeSync(outputFd);}
const report={writes,reads,flushes,bytes,results};fs.writeFileSync('/tmp/safe-python-type-mutation-services.json',JSON.stringify(report));console.log({writes,reads,flushes,bytes,cases:results.length,failed:results.filter(row=>!row.matches)});

