import _codecs, json, random, sys, unicodedata
assert sys.version_info[:3] == (3, 14, 7)
assert unicodedata.unidata_version == '16.0.0'
for wide, seed, count in [(False, 9147, 8000), (True, 14716, 24000)]:
    r = random.Random(seed)
    rows = []
    for i in range(count):
        if wide:
            width = r.choice([8, 16, 32])
            order = r.choice([-1, 0, 1])
            data = bytes(r.choices([0,1,65,127,128,159,160,191,192,194,216,219,220,223,224,237,239,240,244,254,255], k=r.randrange(20)))
        else:
            width = 7
            data = bytes(r.choices(b'+-AZ09/\x00\x80\xff\\~', k=r.randrange(16)))
        policy = r.choice(['strict','ignore','replace','surrogateescape','surrogatepass','backslashreplace'])
        final = r.choice([False, True])
        try:
            function = getattr(_codecs, 'utf_' + str(width) + ('_decode' if width < 16 else '_ex_decode'))
            value = function(data, policy, final) if width < 16 else function(data, policy, order, final)
            result = {'text': list(map(ord, value[0])), 'consumed': value[1]}
            if width >= 16:
                result['byteorder'] = value[2]
        except UnicodeDecodeError as error:
            result = {'error': [error.encoding, list(error.object), error.start, error.end, error.reason]}
        row = dict(width=width, order=order) if wide else {}
        row.update(input=list(data), policy=policy, final=final, result=result)
        rows.append(row)
    with open('/tmp/safe-python-malformed-reproduced-' + ('wide' if wide else 'utf7') + '.json', 'w') as output:
        json.dump(rows, output)

